/* Same-domain projections on the existing diet/calendar/intake routes. */
(function(root){'use strict';const M=root.NutriHealthDemo,E=root.NutriRegistrationEntry,q=new URLSearchParams(root.location.search),routePath=root.location.pathname.split('/').pop(),path=/^(diet|intake|health-calendar)$/.test(routePath)?routePath+'.html':routePath;
// Local immutable envelopes. The shared entry owns the single pending command.
const BUILD='registration-web-v3-c1',FIELDS=['mode','accountId','protocolVersion','epoch','generation','revision'];
const clone=value=>JSON.parse(JSON.stringify(value));
const stable=value=>value&&typeof value==='object'?(Array.isArray(value)?'['+value.map(stable).join(',')+']':'{'+Object.keys(value).sort().map(k=>JSON.stringify(k)+':'+stable(value[k])).join(',')+'}'):JSON.stringify(value);
const same=(a,b)=>stable(a)===stable(b);
const contextOf=s=>Object.fromEntries(FIELDS.map(k=>[k,s.meta[k]]));
const sameContext=(a,b,revision=true)=>!!a&&!!b&&FIELDS.every(k=>!revision&&k==='revision'||a[k]===b[k]);
function freeze(value){if(value&&typeof value==='object'){Object.values(value).forEach(freeze);Object.freeze(value);}return value;}
function currentState(store,s){try{return !!s&&sameContext(contextOf(s),store.context());}catch(_){return false;}}
function rowMatches(rows,row,key='id'){const selected=rows.filter(r=>r[key]===row[key]);return selected.length===1&&same(selected[0],row);}
function healthPostcondition(h,input){
 if(input.type==='append'||input.type==='edit')return input.rows.every(row=>rowMatches(h[input.list]||[],row));
 if(input.type==='recipe')return h.recipeSelections.filter(id=>id===input.id).length===1;
 if(input.type==='check'){const rows=h.reminderChecks.filter(r=>r.reminderId===input.row.reminderId&&r.date===input.row.date);return rows.length===1&&same(rows[0],input.row);}
 if(input.type==='toggle'){const rows=h.reminders.filter(r=>r.id===input.id);return rows.length===1&&rows[0].enabled===input.enabled&&same(rows[0],input.row);}
 return false;
}
function reconcileHealth({state,input,context}){
 const changed={status:'changed',message:'当前记录或账号已变化；原操作回执未确认。请明确停止重试并重新核对，不能自动套用新版本。'};
 if(!state||!state.health||!sameContext(contextOf(state),context,false))return changed;
 if(sameContext(contextOf(state),context)&&same(state,input.base))return {status:'base',message:'当前根记录仍与本次原始版本一致，可明确重试原输入；尚未取得原操作回执。'};
 if(state.meta.revision!==context.revision+1||!healthPostcondition(state.health,input))return changed;
 return {status:'match',message:'当前记录与本次输入一致，原操作回执未确认'};
}
function applyHealth(h,input,tx){
 if(input.type==='append'){
  if(input.list==='messages'&&h.messages.length+input.rows.length>120)throw Error('演示对话已达上限，请在设置中明确重置后继续。');
  const rows=h[input.list]||(h[input.list]=[]);if(input.rows.some(row=>rows.some(r=>r.id===row.id)))throw Error('原记录标识已存在，请核对原操作结果。');
  input.rows.forEach(row=>rows.push(clone(row)));return null;
 }
 if(input.type==='edit'){const rows=h[input.list];const targets=rows.filter(r=>r.id===input.rows[0].id);if(targets.length!==1)throw Error('原编辑目标已不存在或不唯一，不能自动新增。');rows[rows.indexOf(targets[0])]=clone(input.rows[0]);return null;}
 if(input.type==='recipe'){const n=h.recipeSelections.filter(id=>id===input.id).length;if(n>1)throw Error('备选记录重复，请核对。');if(n===1)return tx.noop(null);h.recipeSelections.push(input.id);return null;}
 if(input.type==='check'){if(h.reminders.filter(r=>r.id===input.row.reminderId).length!==1)throw Error('提醒不存在或不唯一');const rows=h.reminderChecks.filter(r=>r.reminderId===input.row.reminderId&&r.date===input.row.date);if(rows.length){if(rows.length===1&&same(rows[0],input.row))return tx.noop(null);throw Error('打卡记录已变化，请核对。');}h.reminderChecks.push(clone(input.row));return null;}
 if(input.type==='toggle'){const rows=h.reminders.filter(r=>r.id===input.id);if(rows.length!==1)throw Error('提醒不存在或不唯一');rows[0].enabled=input.enabled;return null;}
 throw Error('不支持的健康记录操作');
}


function load(src){return new Promise((resolve,reject)=>{const el=document.createElement('script');el.src=src;el.onload=resolve;el.onerror=reject;document.body.append(el);});}
async function mount(){
if(q.get('legacy')==='1'){const list=path==='diet.html'?['diet.js']:path==='health-calendar.html'?['health-calendar.js']:['book-data.js','data.js','expressions.js','subpages.js','adapter.js'];list.reduce((p,src)=>p.then(()=>load(src)),Promise.resolve()).catch(()=>{const p=document.createElement('p');p.textContent='旧版脚本加载失败，请刷新重试。';document.body.prepend(p);});return;}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const page=document.createElement('main');page.className='hdp-page';Array.from(document.body.children).forEach(el=>{if(el.tagName!=='SCRIPT'&&!el.hasAttribute('data-registration-entry')&&!el.hasAttribute('data-shell-nav')&&!el.classList.contains('nutri-demo-label'))el.hidden=true;});document.body.classList.add('hdp-active');document.body.append(page);
const S=root.NutriDemo;
let state,date,filter='all',editing=null,editorRevision=null,editorContext=null,editorState=null,busy=false,active=true,viewVersion=0,dirty=false,deferred=false,editorRetired=false;
root.addEventListener('pagehide',()=>{active=false;viewVersion++;unsubscribe?.();});let unsubscribe=null;
let initializing=false,initSerial=0,controller=null;
async function initialize(){
 if(!active||initializing||controller||E.hasPending())return null;const ticket=++initSerial,guard=()=>active&&ticket===initSerial;initializing=true;page.textContent='请在共享入口确认并加载合成演示记录…';
 try{if(E?.buildId!=='registration-entry-v3-c1'||S?.protocolVersion!==3)throw Error('入口版本不匹配');S.defineDomain('health',M.seed);await S.initialize({domains:['health'],guard});if(!guard())return null;state=S.read();if(!currentState(S,state))throw Error('记录已变化，请重新加载核对。');date=M.validDate(q.get('date'))?q.get('date'):state.health.demoDate;controller=mountReady();if(ticket>1)E.report(S.status().persistent?'合成健康记录已重新加载，请核对当前记录。':'合成健康记录已重新加载；仅本页内存，刷新或导航后丢失。');return controller;}
 catch(e){if(!guard())return null;page.innerHTML='<h1>合成记录暂不可读</h1><p>'+esc(e.message)+'</p><p>结果尚未核对，现有数据保留。可明确重试加载当前合成记录；不会清空或另建副本。</p><button type="button" data-health-init-retry>重新加载合成健康记录</button>';const button=page.querySelector('[data-health-init-retry]');button.addEventListener('click',()=>{if(!guard()||initializing||button!==page.querySelector('[data-health-init-retry]')||E.hasPending())return;button.disabled=true;void initialize();});E?.report(e.message);return null;}
 finally{if(ticket===initSerial)initializing=false;}
}
function mountReady(){
let foodCapture=null;
const labels={breakfast:'早餐',lunch:'午餐',dinner:'晚餐',snack:'加餐'};
const kind=path==='health-calendar.html'?'calendar':path==='intake.html'?'intake':'diet';
const V=root.NutriDietReference01;if(kind!=='calendar'&&(V?.buildId!=='diet-reference01-v1'||typeof V.renderDietOverview!=='function'||typeof V.renderIntake!=='function'))throw Error('饮食呈现组件未完整加载，请重新加载；现有记录保留。');
const title={calendar:'健康日历',intake:'今日记录',diet:'饮食册'}[kind];
function read(){const next=S.read();if(!currentState(S,next))throw Error('记录已变化，请重新核对。');return next.health;}
function projections(h){return M.calendarEntries(h).concat(h.water.map(w=>({id:w.id,date:w.date,time:'',type:'water',text:'饮水 '+w.ml+' ml',source:w.source,synthetic:true})),(h.dailyNotes||[]).map(n=>({id:n.id,date:n.date,time:'',type:'self',text:'日常自述 · '+n.feeling,source:n.source,synthetic:true})));}
function totals(h){const s=M.mealSummary(h,date),water=h.water.filter(w=>w.date===date).reduce((n,w)=>n+w.ml,0);return `<div class="hdp-grid">${[['kcal','热量','kcal'],['carb','碳水','g'],['fat','脂肪','g'],['protein','蛋白质','g']].map(([k,l,u])=>`<div class="hdp-stat" data-nutrient="${k}"><strong>${s.totals[k].value??'未知'} <small>${u}</small></strong><span>${l} · 有值 ${s.totals[k].known}/${s.totals[k].total} 条</span><progress max="${s.totals[k].total||1}" value="${s.totals[k].known}" aria-label="${l}数值条目覆盖"></progress></div>`).join('')}<div class="hdp-stat"><strong>${water} ml</strong><span>演示饮水合计</span></div><div class="hdp-stat"><strong>${s.count} 条</strong><span>餐食记录</span></div></div><p>条形只表示数值覆盖，不是目标达成率；未知不计作 0。默认数值为合成展示，非测量或数据库计算。</p>`;}
function timeline(h){const rows=projections(h).filter(r=>r.date===date&&(filter==='all'||r.type===filter));return rows.length?`<ul class="hdp-list">${rows.map(r=>`<li><strong>${esc(r.text)}</strong><small>${esc(r.date)} ${esc(r.time)} · ${esc(r.source)} · 合成记录</small>${r.type==='diet'?`<button type="button" data-action="edit" data-id="${r.id}">查看 / 修改</button>`:''}</li>`).join('')}</ul>`:'<p class="hdp-empty">这天暂无此类合成记录；没有记录不代表没有发生。</p>';}
function days(h){const month=date.slice(0,7),count=new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate();const all=projections(h);return `<div class="hdp-calendar">${Array.from({length:count},(_,i)=>{const key=month+'-'+String(i+1).padStart(2,'0'),n=all.filter(r=>r.date===key).length;return `<button type="button" data-action="date" data-date="${key}" aria-pressed="${key===date}">${i+1}<small>${n?n+' 条':'—'}</small></button>`;}).join('')}</div>`;}
// Diet-specific presentation of the same verified health domain; no legacy store.
let dietIdeaIndex=0,dietLarge=false;
function dietInspiration(){const recipes=M.RECIPES||[],r=recipes[dietIdeaIndex%Math.max(recipes.length,1)];return r?`<h3 class="recipe-title">${esc(r.name)}</h3><p class="recipe-ingredients">${r.ingredients.map(esc).join(' · ')}<br>约 ${esc(r.minutes)} 分钟 · 通用做法示例</p><details class="recipe-detail"><summary>查看做法与食材提醒</summary><ol>${r.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p class="hint">需核对的过敏原：${r.allergens.length?r.allergens.map(esc).join('、'):'请逐项核对食材'}。示例不会自动计入已吃记录。</p></details>`:'<p class="hint">暂无做法示例，可以直接记录自己的食物。</p>';}
function dietView(h){const s=M.mealSummary(h,date),meals=h.meals.filter(r=>r.date===date),slots=['breakfast','lunch','dinner'];
return V.renderDietOverview({date,summary:s,large:dietLarge,slots:slots.map(key=>{const rows=meals.filter(row=>row.slot===key);return {key,label:labels[key],rows,summary:M.mealSummary({...h,meals:rows},date)};})})+`<section class="panel diet-inspiration"><div class="section-head"><div><span class="eyebrow">下一餐灵感 · 配方示例</span><h2>下一餐搭配建议</h2></div><button type="button" data-action="diet-idea">换一组 <span aria-hidden="true">↻</span></button></div><div data-diet-inspiration>${dietInspiration()}</div><button class="primary" type="button" data-action="meal">吃了这份？调整后记录</button><button class="secondary" type="button" data-action="meal">＋ 记录其他食物</button></section><div data-editor></div><section class="tools-card"><h2>把了解变成日常</h2><button class="tool-row" type="button" data-action="meal"><span class="tool-symbol" aria-hidden="true">＋</span><span><b>记录一餐</b><small>从吃了什么、吃了多少开始</small></span><span aria-hidden="true">›</span></button><a class="tool-row" href="aiAgent.html?view=recipes"><span class="tool-symbol" aria-hidden="true">♧</span><span><b>养生食谱</b><small>按食材与做法，找到下一餐灵感</small></span><span aria-hidden="true">›</span></a><a class="tool-row" href="health-calendar.html?date=${date}"><span class="tool-symbol" aria-hidden="true">▦</span><span><b>健康日历</b><small>回看同一份记录，不必重复填写</small></span><span aria-hidden="true">›</span></a></section><section class="panel saved-panel"><div class="section-head"><h2>这天的饮食记录</h2><a href="health-calendar.html?date=${date}">查看日历 →</a></div>${[...slots,'snack'].map(slot=>{const rows=meals.filter(r=>r.slot===slot);if(slot==='snack'&&!rows.length)return '';return `<section class="diet-meal-group" id="hdp-meals-${slot}"><h3>${labels[slot]}</h3>${rows.length?rows.map(r=>`<div class="saved-row"><strong>${esc(r.name)}</strong><p>${esc(r.time)}${r.grams===null||r.grams===undefined?' · 份量未知':' · '+esc(r.grams)+' g'} · ${r.kcal===null||r.kcal===undefined?'热量未知':esc(r.kcal)+' kcal'}</p><button type="button" data-action="edit" data-id="${esc(r.id)}">查看 / 修改</button></div>`).join(''):'<p class="hint">这天还没有此餐记录。</p>'}</section>`;}).join('')}</section><p data-status role="status" aria-live="polite"></p><details class="diet-about"><summary>关于建议与记录 <span class="hdp-demo-chip">预设演示</span></summary><p>当前显示合成演示记录，不是个人测量。条形只表示已有数值的记录覆盖，不是营养目标；未知值不计作 0。做法示例不是个性化处方，请先核对过敏原和医嘱限制。</p><p>保存继续使用同一合成账号；未开启隔离旧版资料。</p><a href="settings.html">查看数据与保存说明</a></details>`;}
function intakeView(h){const summary=M.mealSummary(h,date),water=h.water.filter(row=>row.date===date).reduce((sum,row)=>sum+row.ml,0);return V.renderIntake({date,summary,water,filter,timelineHtml:timeline(h)});}
function render(){if(!active||!currentState(S,state))return false;const h=state.health;page.classList.toggle('hdp-diet',kind==='diet');page.classList.toggle('diet-large',kind==='diet'&&dietLarge);const html=kind==='diet'?dietView(h):kind==='intake'?intakeView(h):`<header class="hdp-header"><div class="hdp-topbar"><a class="hdp-back" href="aiAgent.html" aria-label="返回小禾助手"><span aria-hidden="true">‹</span> 助手</a><div class="hdp-heading"><h1>${title}</h1><span class="hdp-demo-chip">预设演示</span></div><a class="hdp-about" href="settings.html" aria-label="查看演示与数据说明">说明</a></div><nav class="hdp-segments" aria-label="健康记录页面"><a href="diet.html" ${kind==='diet'?'aria-current="page"':''}>饮食</a><a href="intake.html" ${kind==='intake'?'aria-current="page"':''}>摄入</a><a href="health-calendar.html" ${kind==='calendar'?'aria-current="page"':''}>日历</a><a href="aiAgent.html?view=weekly">周报</a></nav></header><section class="hdp-card"><div class="hdp-date"><label>查看日期<input type="date" data-date-picker value="${date}" required></label><button type="button" data-action="today">演示当天</button></div>${kind==='calendar'?days(h):''}</section><section class="hdp-card"><h2>这天的营养与饮水</h2>${totals(h)}<div class="hdp-tools"><button type="button" data-action="refresh">刷新记录</button><button class="hdp-primary" type="button" data-action="meal">＋ 记一餐</button><button type="button" data-action="water">＋ 记录饮水</button><a href="aiAgent.html?view=daily">日常自述</a></div><div data-editor></div></section><section class="hdp-card"><h2>这天的记录</h2><label>记录类型<select data-filter><option value="all">全部</option><option value="diet" ${filter==='diet'?'selected':''}>餐食</option><option value="water" ${filter==='water'?'selected':''}>饮水</option><option value="health" ${filter==='health'?'selected':''}>健康指标</option><option value="self" ${filter==='self'?'selected':''}>日常自述</option></select></label>${timeline(h)}</section><p data-status role="status" aria-live="polite"></p><p class="hdp-legacy"><a href="${path}?legacy=1">查看隔离的旧版本机记录</a> · 旧版资料不会混入合成账号</p><nav class="hdp-fixed"><a href="shop.html">商城</a><a href="../nutrition-booklet.html">营养册</a><a href="aiAgent.html">AI 助手</a><a href="diet.html">饮食</a><a href="profile.html">我的</a></nav>`;if(!active||!currentState(S,state))return false;foodCapture?.dispose();foodCapture=null;page.innerHTML='<p class="hdp-card">当前：沈先生合成演示 · <a href="personal-food.html">明确进入个人本机饮食记录（独立数据）</a></p>'+html;return true;}
function status(text){const node=page.querySelector('[data-status]');if(node)node.textContent=text;else E.report(text);}

let editorReturnFocus=null;
function rememberEditorTrigger(trigger){if(!trigger)return;const action=trigger.dataset.action,id=trigger.dataset.id||'';const matches=Array.from(page.querySelectorAll('[data-action]')).filter(n=>n.dataset.action===action&&(n.dataset.id||'')===id);editorReturnFocus={node:trigger,action,id,index:matches.indexOf(trigger)};}
function revealEditor(){const target=page.querySelector('[data-editor]');if(!target||!active)return;target.setAttribute('tabindex','-1');target.setAttribute('role','region');target.setAttribute('aria-label','记录编辑');target.focus?.({preventScroll:true});target.scrollIntoView?.({block:'start',behavior:'auto'});}
function restoreEditorTrigger(){const saved=editorReturnFocus;editorReturnFocus=null;if(!saved||!active)return;const matches=Array.from(page.querySelectorAll('[data-action]')).filter(n=>n.dataset.action===saved.action&&(n.dataset.id||'')===saved.id);const target=saved.node.isConnected?saved.node:matches[saved.index];if(!target||target.disabled||!target.isConnected)return;target.focus?.({preventScroll:true});target.scrollIntoView?.({block:'nearest',behavior:'auto'});}
function mountFoodCapture(original,start='camera'){const target=page.querySelector('[data-editor]');target.innerHTML='<button type="button" data-action="cancel">关闭记录</button><div data-capture></div>';const ticket=viewVersion,context=freeze(clone(editorContext)),base=clone(editorState),recordId=original?.id||'capture-'+Date.now()+'-'+Math.random().toString(36).slice(2);const guard=()=>active&&viewVersion===ticket&&!editorRetired;
foodCapture=root.NutriFoodCaptureView.mount(target.querySelector('[data-capture]'),{date,id:recordId,initial:original?clone(original):null,start:original?'manual':start,onDirty:()=>{dirty=true;},isLocked:()=>busy||E.hasPending()||!guard(),save:async row=>{if(busy||E.hasPending()||!guard())throw Error('当前记录或保存状态已变化，请先核对');const command={type:original?'edit':'append',list:'meals',rows:[row]},input=freeze(clone({...command,base}));busy=true;try{return await E.execute({kind:'health-projection:'+command.type+':meals',context,input,guard,run:({input,context})=>S.transact((draft,tx)=>applyHealth(draft.health,input,tx),{context,expectedRevision:context.revision,guard,reason:'health-projection:'+input.type}),onSuccess:receipt=>{if(!guard()||!receipt?.state||!currentState(S,receipt.state)){status('保存回执与当前状态尚待核对，填写保留');return;}if(present(receipt.state,date,filter,true)){status('合成餐食已保存，照片未存入合成账号');restoreEditorTrigger();}},onError:error=>status((error.message||'保存未确认')+'；填写保留'),reconcile:reconcileHealth});}finally{busy=false;}}});}
function form(type,id,start='camera',trigger=null){if(!E.confirmLeave(dirty,'放弃当前未保存填写，打开另一条演示记录？'))return;if(!currentState(S,state)){status('显示版本已变化，请刷新核对。');return;}const meal=state.health.meals.find(m=>m.id===id);if(id&&!meal){status('原餐食目标不存在，不能新增替代。');return;}rememberEditorTrigger(trigger);editing={type,id:id||null,date};viewVersion++;dirty=false;editorRetired=false;editorState=clone(state);editorRevision=state.meta.revision;editorContext={mode:state.meta.mode,accountId:state.meta.accountId,protocolVersion:state.meta.protocolVersion,epoch:state.meta.epoch,generation:state.meta.generation,revision:state.meta.revision};foodCapture?.dispose();foodCapture=null;if(type==='meal'&&root.NutriFoodCaptureView){mountFoodCapture(meal,start);revealEditor();return;}page.querySelector('[data-editor]').innerHTML=`<form class="hdp-form" data-form="${type}" data-health-editor="${viewVersion}"><h3>${type==='water'?'记录演示饮水':meal?'修改这餐合成记录':'添加合成餐食'}</h3><p>归属 ${date}；只保存到合成账号。</p>${type==='water'?'<label>饮水 ml<input name="ml" type="number" min="10" max="2000" value="250" required></label>':`<label>菜名<input name="name" value="${esc(meal?.name||'')}" maxlength="100" required></label><div class="hdp-grid"><label>餐次<select name="slot">${Object.entries(labels).map(([k,l])=>`<option value="${k}" ${meal?.slot===k?'selected':''}>${l}</option>`).join('')}</select></label><label>时间<input name="time" type="time" value="${meal?.time||'12:00'}" required></label></div><div class="hdp-grid">${[['grams','份量 g'],['kcal','热量 kcal'],['carb','碳水 g'],['protein','蛋白质 g'],['fat','脂肪 g']].map(([k,l])=>`<label>${l}（可空）<input name="${k}" type="number" min="0" max="10000" step="any" value="${meal?.[k]??''}"></label>`).join('')}</div>`}<label><input name="consent" type="checkbox" required>确认仅使用合成演示数据并保存在本机</label><button class="hdp-primary" type="submit">确认保存</button> <button type="button" data-action="cancel">取消</button><p data-form-status role="alert"></p></form>`;revealEditor();}
function present(next,nextDate=date,nextFilter=filter,closeEditor=false){const previous={state,date,filter};state=next;date=nextDate;filter=nextFilter;try{if(!render())throw Error('最终显示未能核对，请刷新。');if(closeEditor){viewVersion++;editing=null;dirty=false;editorRetired=false;}return true;}catch(e){state=previous.state;date=previous.date;filter=previous.filter;status(e.message+' 当前填写及原版本保留，未确认刷新成功。');return false;}}
function fresh(){try{const next=S.read();if(!currentState(S,next))throw Error('记录再次变化，请明确刷新核对。');if(editing)return false;return present(next);}catch(e){status(e.message+' 当前填写保留。');return false;}}
function refreshView(nextDate=date,nextFilter=filter){try{const next=S.read();if(!currentState(S,next))throw Error('记录再次变化，请明确刷新核对。');return present(next,nextDate,nextFilter,true);}catch(e){status(e.message+' 当前填写及原版本保留。');return false;}}
function retiredDraft(message){status(message);}
if(!render())throw Error('初始记录显示未能核对，请重新加载。');
page.addEventListener('input',e=>{const f=e.target.closest('form[data-form]');if(f&&f.dataset.healthEditor===String(viewVersion))dirty=true;});
page.addEventListener('click',e=>{const link=e.target.closest('a[href]');if(link){if(!E.confirmLeave(dirty,'离开会丢失本页填写和原操作重试身份；已发生的写入不会撤销。是否继续？'))e.preventDefault();return;}if(busy)return;const b=e.target.closest('[data-action]');if(!b)return;const owner=b.closest('form[data-form]');if(owner&&owner.dataset.healthEditor!==String(viewVersion))return;const a=b.dataset.action;if(E.hasPending()){status('先在入口核对原操作，或明确停止重试。当前填写保留。');return;}if(kind==='diet'&&a==='diet-size'){dietLarge=!dietLarge;page.classList.toggle('diet-large',dietLarge);b.setAttribute('aria-pressed',String(dietLarge));return;}if(kind==='diet'&&a==='diet-idea'){dietIdeaIndex++;page.querySelector('[data-diet-inspiration]').innerHTML=dietInspiration();return;}if(a==='refresh'){if(!E.confirmLeave(dirty,'放弃当前填写并读取最新记录？'))return;if(refreshView())status('已读取当前记录，请重新打开表单。');return;}if(['date','today'].includes(a)){if(!E.confirmLeave(dirty,'放弃尚未保存的演示填写，切换日期？'))return;refreshView(a==='today'?state.health.demoDate:b.dataset.date);}else if(a==='meal-manual')form('meal',null,'manual',b);else if(a==='meal'||a==='water')form(a,null,'camera',b);else if(a==='edit')form('meal',b.dataset.id,'manual',b);else if(a==='cancel'){if(!E.confirmLeave(dirty,'放弃当前填写并关闭？'))return;foodCapture?.dispose();foodCapture=null;viewVersion++;editing=null;dirty=false;page.querySelector('[data-editor]').innerHTML='';restoreEditorTrigger();}});
page.addEventListener('change',e=>{const form=e.target.closest?.('form[data-form]');if(form&&form.dataset.healthEditor===String(viewVersion))dirty=true;if(busy||E.hasPending()){if(e.target.hasAttribute('data-date-picker'))e.target.value=date;else if(e.target.hasAttribute('data-filter'))e.target.value=filter;return;}if(e.target.hasAttribute('data-date-picker')){if(!M.validDate(e.target.value)){status('请选择有效日期');return;}if(!E.confirmLeave(dirty,'放弃尚未保存的演示填写，切换日期？')){e.target.value=date;return;}if(!refreshView(e.target.value))e.target.value=date;}else if(e.target.hasAttribute('data-filter')){if(!E.confirmLeave(dirty,'放弃尚未保存的填写，切换记录类型？')){e.target.value=filter;return;}if(!refreshView(date,e.target.value))e.target.value=filter;}});
page.addEventListener('submit',async e=>{
 const f=e.target;if(!f.dataset.form)return;e.preventDefault();if(busy||E.hasPending()||!editing||f.dataset.healthEditor!==String(viewVersion)||!f.reportValidity())return;
 const v=n=>f.elements[n].value,recordId=editing.id||'page-'+Date.now()+'-'+Math.random().toString(36).slice(2),targetDate=editing.date,ticket=viewVersion,context=freeze(clone(editorContext));
 const guard=()=>active&&ticket===viewVersion;
 try{if(!f.elements.consent.checked)throw Error('请先确认合成演示数据');let command;
 if(f.dataset.form==='water'){const temp={demoDate:targetDate,water:[]};M.addWater(temp,v('ml'),recordId);command={type:'append',list:'water',rows:temp.water};}
 else{const previous=editing.id?editorState.health.meals.find(m=>m.id===editing.id):null;const row={...clone(previous||{}),id:recordId,date:targetDate,time:v('time'),slot:v('slot'),name:M.clean(v('name'),100),source:'user-demo-entry',synthetic:true,note:'合成手工演示，非测量'};['grams','kcal','carb','protein','fat'].forEach(k=>{row[k]=v(k)===''?null:Number(v(k));if(row[k]!==null&&(!Number.isFinite(row[k])||row[k]<0||row[k]>10000))throw Error('请输入范围内数值或留空');});if(previous?.nutrients){row.nutrients=clone(previous.nutrients);for(const k of ['kcal','carb','protein','fat'])row.nutrients[k]={...row.nutrients[k],value:row[k],unit:k==='kcal'?'kcal':'g',basis:'consumed',status:row[k]===null?'unknown':'user-entered',source:{kind:'user-entry',verified:false}};}if(previous)row.revision=(previous.revision||0)+1;command={type:editing.id?'edit':'append',list:'meals',rows:[row]};}
 const input=freeze(clone({...command,base:editorState}));busy=true;f.querySelectorAll('button,input,select,textarea').forEach(b=>b.disabled=true);
 await E.execute({kind:'health-projection:'+command.type+':'+command.list,context,input,guard,
 run:({input,context})=>S.transact((draft,tx)=>applyHealth(draft.health,input,tx),{context,expectedRevision:context.revision,guard,reason:'health-projection:'+input.type}),
 onSuccess:receipt=>{if(!guard())return;if(!receipt?.state||typeof receipt.committed!=='boolean'||!currentState(S,receipt.state)){fresh();retiredDraft('已有更新的数据；旧操作结果未清空当前填写，请刷新核对。');return;}if(!present(receipt.state,date,filter,true)){status('操作回执已核验，最终显示未能核对；当前填写与原版本保留，请刷新。');return;}deferred=false;restoreEditorTrigger();status(S.status().persistent?'已保存：各页面使用同一合成记录。':'仅本页临时演示，刷新或导航到其他页面丢失。');},
 onError:error=>{if(guard()){f.querySelector('[data-form-status]').textContent=(error.message||'结果尚未核对')+' 当前填写保留。';status('请在共享入口核对原操作；未据此判断是否写入。');}},reconcile:reconcileHealth});
 }catch(error){if(guard())f.querySelector('[data-form-status]').textContent=error.message+' 当前填写保留。';}finally{busy=false;if(active)f.querySelectorAll('button,input,select,textarea').forEach(b=>b.disabled=E.hasPending());if(deferred&&!E.hasPending()){deferred=false;fresh();}}
});
root.addEventListener('beforeunload',e=>{if(active&&(dirty||E.hasPending())){e.preventDefault();e.returnValue='';}});
const unsubEntry=E.subscribe?.(()=>{if(active&&kind==='intake'&&deferred&&!busy&&!E.hasPending()&&!editing){deferred=false;fresh();}if(active&&!busy)page.querySelectorAll('[data-editor] input,[data-editor] select,[data-editor] button').forEach(b=>b.disabled=E.hasPending()||editorRetired);});
unsubscribe=S.subscribe(next=>{if(!active)return;if(!next||!next.health||!currentState(S,next)){if(currentState(S,state))return;status('当前记录不可读或通知已过时；填写保留，请从入口核对。');return;}const identityChanged=!sameContext(contextOf(next),contextOf(state),false);if(identityChanged){foodCapture?.dispose();foodCapture=null;viewVersion++;editorRetired=true;page.querySelectorAll('[data-editor] input,[data-editor] select,[data-editor] button').forEach(b=>b.disabled=true);status('共享账号身份已变化；旧表单授权失效，请重新打开后核对。');}if(busy||E.hasPending()){deferred=true;return;}if(editing){status('记录已更新；当前填写与原始版本保留，保存前将核对版本。');return;}present(next);});
// Only the intake drawer is restored here; the self intake projection remains unchanged.
const familyDrawer=kind==='intake'&&root.NutriFamilyDrawer?root.NutriFamilyDrawer.attach({
 requestOpen(){if(!active||busy||E.hasPending()||!currentState(S,state))return false;if(!E.confirmLeave(dirty,'打开家庭抽屉会放弃本人页未保存填写，是否继续？'))return false;return refreshView();},
 valid:()=>active,
 block(value){page.inert=value;}
}):null;
if(!S.status().persistent)status('明确选择的本页临时演示；刷新或导航到其他页面会丢失。');
root.NutriHealthProjection=Object.freeze({buildId:BUILD,read,projections,render});
const disposeMounted=()=>{foodCapture?.dispose();foodCapture=null;unsubEntry?.();familyDrawer?.destroy();};
root.addEventListener('pagehide',disposeMounted,{once:true});
return {destroy(){disposeMounted();root.removeEventListener?.('pagehide',disposeMounted);active=false;initSerial++;viewVersion++;unsubscribe?.();}};
}
return initialize();
}
if(E?.buildId==='registration-entry-v3-c1')E.register('health-pages',{buildId:BUILD,mount});
else {const p=document.createElement('p');p.textContent='健康记录入口版本不匹配，未启用写入。';document.body.append(p);}
})(window);
